<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { Ellipsis, Filter, Plus, RefreshCw, Search, X } from '@lucide/vue'
import { useRoute } from 'vue-router'

import FoundationButton from './FoundationButton.vue'
import FoundationProductShell from './FoundationProductShell.vue'
import FoundationStatus from './FoundationStatus.vue'
import { VISUAL_OVERVIEW_FIXTURES, VISUAL_RUNTIME_FIXTURES, VISUAL_TASK_FIXTURE, VISUAL_VALIDATION_MARKER } from './visualValidationFixtures'
import { dataSourceUiFixtureForSearch } from '@/views/dataSourceUiFixture'

type Page = 'overview' | 'sources' | 'builder' | 'detail'

const route = useRoute()
const page = computed<Page>(() => ['overview', 'sources', 'builder', 'detail'].includes(String(route.params.page)) ? route.params.page as Page : 'overview')
const drawerOpen = ref(true)
const menuOpen = ref(false)
const drawerElement = ref<HTMLElement>()
const newDataSourceButton = ref<{ $el: HTMLButtonElement }>()
const sources = dataSourceUiFixtureForSearch('?uiFixture=data-sources') ?? []
const overviewFixtures = VISUAL_OVERVIEW_FIXTURES
const runtimeFixtures = VISUAL_RUNTIME_FIXTURES
const taskFixture = VISUAL_TASK_FIXTURE
const fixtureMarker = VISUAL_VALIDATION_MARKER
function testStatus(source: typeof sources[number]) {
  return source.lastTestStatus === 'SUCCEEDED' ? ['success', '最近测试成功']
    : source.lastTestStatus === 'FAILED' ? ['danger', '连接失败']
      : source.lastTestStatus === 'INVALIDATED' ? ['warning', '结果已失效']
        : source.lastTestStatus === 'PENDING' ? ['info', '测试中']
          : source.lastTestStatus === 'UNKNOWN' ? ['neutral', '状态待确认'] : ['neutral', '未测试']
}
function runtimeTone(acceptsNewTasks: boolean) { return acceptsNewTasks ? 'success' : 'warning' }
function runtimeLabel(acceptsNewTasks: boolean) { return acceptsNewTasks ? '可接收新任务' : '不可接收新任务' }
function operationLabel(state: string) { return ({ WAITING_SCHEDULE: '等待 Agent 领取', STARTING: '正在启动', FAILED: '导出失败' })[state] ?? '状态核对中' }
function closeDrawer() {
  drawerOpen.value = false
  void nextTick(() => newDataSourceButton.value?.$el.focus())
}
function trapDrawerFocus(event: KeyboardEvent) {
  const focusable = drawerElement.value?.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), summary, [tabindex]:not([tabindex="-1"])')
  if (!focusable || focusable.length === 0) return
  const first = focusable[0]
  const last = focusable[focusable.length - 1]
  if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus() }
  if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus() }
}
watch(drawerOpen, (open) => {
  if (!open) return
  menuOpen.value = false
  void nextTick(() => drawerElement.value?.focus())
})
</script>

<template>
  <FoundationProductShell :active="page">
    <section v-if="page === 'overview'" class="vf-workspace vf-overview">
      <header class="vf-page-header"><div><h1>运行概览</h1><p>当前运行事实、需要处理的任务与运行环境状态。</p></div><span class="vf-meta">{{ fixtureMarker }}</span></header>
      <div class="vf-kpis"><div><small>运行中任务</small><strong>{{ overviewFixtures.filter((item) => item.state === 'RUNNING').length }}</strong><span>任务状态：RUNNING</span></div><div><small>等待调度</small><strong>{{ overviewFixtures.filter((item) => item.state === 'WAITING_SCHEDULE').length }}</strong><span>任务状态：WAITING_SCHEDULE</span></div><div><small>失败 / 阻塞</small><strong>{{ overviewFixtures.filter((item) => item.category === 'NEEDS_ATTENTION').length }}</strong><span>需要人工判断</span></div></div>
      <div class="vf-two-col vf-overview-state"><section><h2>运行时健康</h2><ul class="vf-fact-list"><li v-for="runtime in runtimeFixtures" :key="runtime.node.id"><FoundationStatus :tone="runtimeTone(runtime.node.acceptsNewTasks) as any">{{ runtimeLabel(runtime.node.acceptsNewTasks) }}</FoundationStatus><span>{{ runtime.node.heartbeatStatus }} · {{ runtime.node.environmentStatus }} · {{ runtime.node.capacityStatus }}</span></li></ul><h2>需要关注</h2><ul class="vf-attention"><li v-for="item in overviewFixtures.filter((entry) => entry.category === 'NEEDS_ATTENTION')" :key="item.id"><FoundationStatus tone="danger">{{ item.state }}</FoundationStatus><b>{{ item.id }}</b><span>{{ item.occurredAt }}</span></li></ul></section><section><h2>最近活动</h2><ol class="vf-timeline"><li v-for="item in overviewFixtures.filter((entry) => entry.category !== 'NEEDS_ATTENTION')" :key="item.id">{{ item.occurredAt }} · {{ item.id }} · {{ item.state }}</li></ol></section></div>
    </section>

    <section v-else-if="page === 'sources'" class="vf-workspace vf-sources">
      <header class="vf-page-header"><div><h1>数据源管理</h1><p>管理可供任务选择的 OceanBase 数据源、基础连接测试与生命周期状态。</p><small>{{ fixtureMarker }}</small></div><FoundationButton ref="newDataSourceButton" variant="primary" @click="drawerOpen = true"><Plus :size="16" />新增数据源</FoundationButton></header>
      <div class="vf-toolbar"><label class="vf-search"><Search :size="16" /><input placeholder="搜索数据源" /></label><select aria-label="环境筛选"><option>环境：全部</option></select><select aria-label="可用性筛选"><option>可用性：全部</option></select><select aria-label="连接测试筛选"><option>连接测试：全部</option></select><FoundationButton variant="utility"><Filter :size="16" />更多筛选</FoundationButton><FoundationButton variant="utility"><RefreshCw :size="16" />刷新</FoundationButton></div>
      <table class="vf-table"><thead><tr><th>数据源</th><th>环境</th><th>Endpoint</th><th>集群 / 租户</th><th>兼容模式</th><th>连接测试</th><th>可用性</th><th>操作</th></tr></thead><tbody><tr v-for="source in sources" :key="source.id" :class="{ selected: source.id === sources[2]?.id }"><td><b>{{ source.displayName }}</b><small>{{ source.username }} · {{ source.defaultDatabase }}</small></td><td>{{ source.environment }}</td><td class="vf-mono">{{ source.host }}:{{ source.port }}</td><td>{{ source.clusterName }}<small>{{ source.tenantName }}</small></td><td>{{ source.compatibilityMode }}</td><td><FoundationStatus :tone="testStatus(source)[0] as any">{{ testStatus(source)[1] }}</FoundationStatus><small>{{ source.lastTestedAt ?? '尚未形成测试事实' }}</small></td><td><FoundationStatus :tone="source.state === 'ENABLED' ? 'success' : 'neutral'">{{ source.state === 'ENABLED' ? '已启用' : '已禁用' }}</FoundationStatus></td><td><FoundationButton variant="utility" icon aria-label="更多操作" @click="menuOpen = !menuOpen"><Ellipsis :size="16" /></FoundationButton></td></tr></tbody></table>
      <div v-if="menuOpen" class="vf-menu"><button>编辑</button><button>测试连接</button><button disabled>启用数据源</button><button disabled>归档数据源</button></div>
      <div v-if="drawerOpen" class="vf-backdrop"><aside ref="drawerElement" class="vf-drawer" role="dialog" aria-modal="true" aria-labelledby="vf-drawer-title" tabindex="-1" @keydown.esc.stop="closeDrawer" @keydown.tab="trapDrawerFocus"><header><div><h2 id="vf-drawer-title">编辑数据源</h2><span>未保存更改</span></div><FoundationButton variant="utility" icon aria-label="关闭" @click="closeDrawer"><X :size="16" /></FoundationButton></header><form><section><h3>基本信息</h3><label>数据源名称<input value="Data mart – sales" /></label><label>环境<select><option>测试</option></select></label></section><section><h3>连接配置</h3><label>兼容模式<select><option>OceanBase MySQL</option></select></label><label>ODP 地址<input value="192.0.2.18" /></label><label>SQL 端口<input value="2883" /></label><label>集群名<input value="obp-test-01" /></label><label>租户名<input value="dwh" /></label></section><section><h3>凭据与高级系统凭据</h3><label>用户名<input value="dwh_reader" /></label><details><summary>高级设置：sys 凭据（可选）</summary><p>仅在已授权时显示，秘密不会回显。</p></details></section><section><h3>通过执行节点测试连接</h3><label>执行节点<select><option>当前没有可测试节点</option></select></label><p class="vf-helper">请先保存连接配置后再测试。</p><FoundationButton disabled>测试连接</FoundationButton></section></form><footer><FoundationButton @click="closeDrawer">取消</FoundationButton><FoundationButton variant="primary">保存更改</FoundationButton></footer></aside></div>
    </section>

    <section v-else-if="page === 'builder'" class="vf-workspace vf-builder">
      <header class="vf-page-header"><div><h1>新建导出任务</h1><p><FoundationStatus tone="neutral">草稿未保存 · 尚未提交</FoundationStatus></p><small>{{ fixtureMarker }}</small></div><FoundationButton>保存草稿</FoundationButton></header>
      <div class="vf-builder-body">
        <ol class="vf-steps"><li class="done">1 选择数据源</li><li class="done">2 选择导出内容</li><li class="done">3 选择导出对象</li><li class="done">4 选择数据格式</li><li class="current">5 执行与输出</li><li>6 预检查与命令</li></ol>
        <div class="vf-builder-work">
          <h2>运行时选择</h2>
          <table class="vf-table vf-runtime"><thead><tr><th></th><th>执行节点</th><th>平台</th><th>运行时环境</th><th>容量</th><th>版本兼容性</th><th>就绪状态</th></tr></thead><tbody><tr v-for="runtime in runtimeFixtures" :key="runtime.node.id" :class="{ selected: runtime.selection === 'SELECTED' }"><td>{{ runtime.selection === 'SELECTED' ? '●' : '○' }}</td><td><b>{{ runtime.node.displayName }}</b><small>{{ runtime.node.id }}</small></td><td class="vf-mono">{{ runtime.node.platform }}</td><td>{{ runtime.node.environmentStatus }}</td><td>{{ runtime.node.capacityStatus }}</td><td><FoundationStatus :tone="runtime.versionCompatibility === 'COMPATIBLE' ? 'success' : 'warning'">{{ runtime.versionCompatibility }}</FoundationStatus></td><td><FoundationStatus :tone="runtimeTone(runtime.node.acceptsNewTasks) as any">{{ runtimeLabel(runtime.node.acceptsNewTasks) }}</FoundationStatus></td></tr></tbody></table>
          <section class="vf-output"><h2>输出配置</h2><div><label>输出类型<select><option>文件系统</option></select></label><label>输出路径<input placeholder="节点完整绝对路径" /></label><label>日志路径（可选）<input placeholder="节点完整绝对路径" /></label><label>执行节点<select><option>{{ runtimeFixtures[0].node.displayName }}</option></select></label></div></section>
          <details class="vf-advanced"><summary>高级设置</summary><p>仅显示当前步骤已授权的导出参数。</p></details>
        </div>
        <aside class="vf-inspector"><h2>运行时详情</h2><dl><dt>节点状态</dt><dd>{{ runtimeFixtures[0].node.heartbeatStatus }}</dd><dt>OS / 架构</dt><dd>{{ runtimeFixtures[0].node.agentFacts?.os }} / {{ runtimeFixtures[0].node.agentFacts?.arch }}</dd><dt>工具版本</dt><dd class="vf-mono">{{ runtimeFixtures[0].toolVersion }}</dd><dt>版本兼容性</dt><dd><FoundationStatus tone="success">{{ runtimeFixtures[0].versionCompatibility }}</FoundationStatus></dd><dt>容量</dt><dd>{{ runtimeFixtures[0].node.capacityStatus }}</dd><dt>就绪状态</dt><dd><FoundationStatus tone="success">{{ runtimeLabel(runtimeFixtures[0].node.acceptsNewTasks) }}</FoundationStatus></dd></dl></aside>
      </div>
      <footer class="vf-sticky-footer"><FoundationButton>上一步</FoundationButton><FoundationButton variant="primary" disabled>继续</FoundationButton></footer>
    </section>

    <section v-else class="vf-workspace vf-detail">
      <header class="vf-page-header"><div><h1>任务详情</h1><p>{{ taskFixture.overview.id }} · {{ fixtureMarker }}</p></div><FoundationStatus tone="danger">导出失败 · 状态核对中</FoundationStatus></header>
      <section><h2>结果 / 失败事实</h2><div class="vf-alert"><FoundationStatus tone="danger">{{ taskFixture.failureSummary }}</FoundationStatus><p>结果：{{ taskFixture.execution.resultSummary?.result }} · 文件数：{{ taskFixture.execution.resultSummary?.fileCount }} · 保存点：{{ taskFixture.execution.resultSummary?.checkpointPresent ? '存在' : '不存在' }}</p></div></section>
      <section><h2>原因</h2><p>{{ taskFixture.failureSummary }}</p><code>{{ taskFixture.failureCode }}</code></section>
      <section><h2>证据</h2><h3>配置快照（只读）</h3><dl class="vf-snapshot"><dt>数据源</dt><dd class="vf-mono">{{ taskFixture.snapshot.dataSourceId }}</dd><dt>导出对象</dt><dd>{{ taskFixture.snapshot.objectSummary }}</dd><dt>输出格式</dt><dd>{{ taskFixture.snapshot.format }}</dd><dt>预检查</dt><dd class="vf-mono">{{ taskFixture.snapshot.precheckId }}</dd><dt>工具版本</dt><dd class="vf-mono">{{ taskFixture.snapshot.toolVersion }}</dd><dt>配置指纹</dt><dd class="vf-mono">{{ taskFixture.snapshot.configFingerprint }}</dd></dl><h3>计划命令（默认脱敏）</h3><pre>{{ taskFixture.command.command }}</pre><h3>日志证据</h3><table class="vf-table"><thead><tr><th>时间</th><th>类型</th><th>完整性</th><th>日志内容</th></tr></thead><tbody><tr v-for="log in taskFixture.logs" :key="log.sourceSeq"><td class="vf-mono">{{ log.receivedAt }}</td><td>{{ log.kind }}</td><td>{{ log.integrityCode }}</td><td>{{ log.message }}</td></tr></tbody></table><h3>操作历史</h3><ol class="vf-timeline"><li v-for="operation in taskFixture.operations" :key="operation.occurredAt">{{ operation.occurredAt }} · {{ operationLabel(operation.state) }}</li></ol></section>
    </section>
  </FoundationProductShell>
</template>

<style>
